#ifndef MT6897_UFS_PLATFORM_H
#define MT6897_UFS_PLATFORM_H
#include <stdint.h>

/* Source-pinned MT6897 subset. No physical callbacks are supplied.
 * mphy-ver=1 delegates PHY management: NEVER execute the legacy ver=0 writes.
 * Every prerequisite below is an assertion by a trusted platform provider,
 * not evidence generated by this module or authentication of firmware.
 */
enum mp_result { MP_OK=0, MP_ARGUMENT=-1, MP_UNVERIFIED=-2, MP_STATE=-3,
                 MP_IO=-4, MP_TIMEOUT=-5 };
enum mp_state { MP_NEW=0, MP_BOUND, MP_PREPARING, MP_PREPARED, MP_RESET_DONE, MP_FAULTED };
enum mp_step { MP_NONE=0, MP_PHY_DELEGATED, MP_RTFF_RESTORED, MP_MTCMOS_ON,
               MP_REF_PRE, MP_REF_REQUEST, MP_REF_ACK, MP_REF_SETTLED, MP_REF_POST };
enum mp_prerequisite {
    MP_EXCLUSIVE=1u<<0, MP_RAILS=1u<<1, MP_PARENT_CLOCKS=1u<<2,
    MP_SIP_ABI=1u<<3, MP_PHY_FIRMWARE=1u<<4, MP_LINK_OFF=1u<<5,
    MP_DMA_QUIESCED=1u<<6
};
#define MP_REQUIRED 0x7fu
#define MP_SIP_UFS 0xc2000276u
#define MP_SIP_REFCLK (1u<<3)
#define MP_SIP_MTCMOS (1u<<9)
#define MP_REFCLK_OFFSET 0x144u
#define MP_REF_TIMEOUT_US 3000u
#define MP_REF_SETTLE_US 32u
enum mp_reset_id { MP_UNIPRO=0, MP_CRYPTO=1, MP_HCI=2 };
struct mp_reset_register { uint64_t bank; uint32_t offset,mask; };
/* Captured ti,syscon-reset tuples: masked updates, STATUS_NONE. This describes
 * the provider operation; it does not perform it or infer reset completion.
 */
int mp_reset_register(unsigned id,int assert_reset,struct mp_reset_register *);
struct mp_sip_request { uint64_t x[8]; };
struct mp_profile {
    uint32_t mphy_version, rtff_mtcmos, va09_supported, prerequisites;
};
struct mp_ops {
    void *context;
    int (*authorise)(void *, uint32_t required);
    /* Provider validates firmware identity/ABI and normalizes a proven
     * success to 0. Raw a0/a1 semantics MUST NOT be guessed here.
     */
    int (*sip)(void *, const struct mp_sip_request *);
    int (*hci_read32)(void *, uint32_t offset, uint32_t *);
    int (*hci_write32)(void *, uint32_t offset, uint32_t);
    void (*barrier)(void *);
    uint64_t (*microseconds)(void *);
    int (*delay_us)(void *, uint32_t minimum);
    /* Matched ti,syscon-reset backend; IDs are the captured DTB order.
     * Success acknowledges the operation, not reset status (unsupported).
     */
    int (*reset)(void *, unsigned id, int assert_reset);
};
struct mp_power {
    struct mp_profile profile;
    struct mp_ops ops;
    enum mp_state state;
    enum mp_step step;
};
/* Zero-initialize and serialize all calls. No allocation or direct SMC/MMIO.
 * Failure latches state; no retry, implicit resource release or reset.
 */
int mp_bind(struct mp_power *, const struct mp_profile *, const struct mp_ops *);
int mp_prepare(struct mp_power *);
int mp_reset_host(struct mp_power *);
/* PREPARED is only this subset's completion, NOT UFS transport readiness.
 * HCE/link startup, regulator/topckgen drivers and DMA ownership are separate.
 */
#endif
